import{_ as e,a0 as a,w as u,s as r,ao as p,I as t,x as o,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"SonoBus：支持跨平台的开源点对点音频流应用 | LCTT x X-CMD","titleTemplate":false,"description":"SonoBus：支持跨平台的开源点对点音频流应用 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SonoBus：支持跨平台的开源点对点音频流应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SonoBus：支持跨平台的开源点对点音频流应用 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support","title":"SonoBus：支持跨平台的开源点对点音频流应用","tag":"202105","desc":""},"relativePath":"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support.md","filePath":"[post].md"}'),d={name:"202105/20210511 SonoBus- An Open Source Peer-to-Peer Audio Streaming App with Cross-Platform Support.md"};function m(f,s,b,g,S,T){const n=a("Link");return u(),r("div",null,[s[21]||(s[21]=p('<h1 id="sonobus-支持跨平台的开源点对点音频流应用" tabindex="-1">SonoBus：支持跨平台的开源点对点音频流应用 <a class="header-anchor" href="#sonobus-支持跨平台的开源点对点音频流应用" aria-label="Permalink to “SonoBus：支持跨平台的开源点对点音频流应用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202105/19/122610n5qgu4443jf4nf4k.jpg" alt=""></p><blockquote><p>一个有趣的开源点对点音频流应用，它提供了一个简单的用户界面和强大的功能。</p></blockquote><h3 id="sonobus-跨平台音频流应用" tabindex="-1">SonoBus: 跨平台音频流应用 <a class="header-anchor" href="#sonobus-跨平台音频流应用" aria-label="Permalink to “SonoBus: 跨平台音频流应用”">​</a></h3><p>如今，音频流服务在听音乐时非常受欢迎。然而，本地音乐集仍然是一种有用的方式，这不需要一直连接到互联网。</p><p>尽管流媒体音乐服务很方便，但你并不真正拥有这些音乐。因此，如果出现许可问题，该平台可能会删除你最喜欢的音乐，而你对此无能为力。</p><p>而有了本地音乐音乐集，你就不会遇到这个问题了。但是，你如何通过设备网络串流你本地的音乐，或者与一个小组分享？</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonobus-screenshot.png?resize=800%2C605&amp;ssl=1" alt=""></p><p>SonoBus 可以成为解决这个问题的办法。不仅仅限于音乐，还包括任何音频，如与一群朋友远程练习音乐或合作制作音乐，为什么不呢？</p><p>让我们来看看它提供了什么。</p><h3 id="sonobus-的功能" tabindex="-1">SonoBus 的功能 <a class="header-anchor" href="#sonobus-的功能" aria-label="Permalink to “SonoBus 的功能”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonus-screenshot-1.png?resize=800%2C619&amp;ssl=1" alt=""></p><p>SonoBus 使用起来比较简单，但提供的功能可能会让人震惊。因此，在继续使用之前，你可能想先知道它能让你做什么：</p><ul><li>能够连接到多个用户</li><li>创建一个有可选密码的小组</li><li>分享来自你的麦克风的音频输入</li><li>分享来自文件的音频流</li><li>支持单声道/立体声</li><li>组内播放</li><li>录制所有人的音频</li><li>能够使个别用户或所有人都静音</li><li>可以通过互联网或本地网络连接</li><li>支持节拍器，用于协作制作音乐或远程练习课程</li><li>支持高质量的音频，最高可达 256Kbps</li><li>输入混音器</li><li>支持声相</li><li>支持有用的效果器（噪声门、压缩器和均衡器）</li><li>可在 JACK 和 ALSA 下工作</li><li>跨平台支持（Windows、macOS、Android、iOS 和 Linux）</li></ul><p>虽然我试图提到所有的基本功能，但你可以在效果器的帮助下得到非常多的控制，来调整音量、质量、延迟，以及音频效果。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/sonobus-official.png?resize=800%2C545&amp;ssl=1" alt=""></p><p>它最好的一点是<strong>跨平台支持</strong>，这使它成为任何用户群的有趣选择，而无论你出于什么原因要串流音频。</p><h3 id="在-linux-中安装-sonobus" tabindex="-1">在 Linux 中安装 SonoBus <a class="header-anchor" href="#在-linux-中安装-sonobus" aria-label="Permalink to “在 Linux 中安装 SonoBus”">​</a></h3>',18)),t("p",null,[s[2]||(s[2]=o("无论你使用什么 Linux 发行版，你都可以轻松地安装 ",-1)),l(n,{href:"https://snapcraft.io/sonobus"},{default:i(()=>[...s[0]||(s[0]=[o("Snap 包",-1)])]),_:1}),s[3]||(s[3]=o("或 ",-1)),l(n,{href:"https://flathub.org/apps/details/net.sonobus.SonoBus"},{default:i(()=>[...s[1]||(s[1]=[o("Flatpak 包",-1)])]),_:1}),s[4]||(s[4]=o("。如果你不想使用它们，你可以手动添加官方仓库来安装：",-1))]),s[22]||(s[22]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;deb http://pkg.sonobus.net/apt stable main&quot; | sudo tee /etc/apt/sources.list.d/sonobus.list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo wget -O /etc/apt/trusted.gpg.d/sonobus.gpg https://pkg.sonobus.net/apt/keyring.gpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install sonobus</span></span></code></pre></div><p>你也可以通过其官方网站为你喜欢的平台下载它。</p>`,2)),t("ul",null,[t("li",null,[l(n,{href:"https://sonobus.net/"},{default:i(()=>[...s[5]||(s[5]=[o("SonoBus",-1)])]),_:1})])]),s[23]||(s[23]=t("h3",{id:"总结",tabindex:"-1"},[o("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),s[24]||(s[24]=t("p",null,"SonoBus 是一个令人印象深刻的音频流应用，有很多潜在的用途，但它也有一些问题，可能不是每个人的完美解决方案。",-1)),s[25]||(s[25]=t("p",null,"例如，我注意到桌面应用占用大量的系统资源，所以这对较旧的系统来说可能是个问题。",-1)),s[26]||(s[26]=t("p",null,"另外，Play Store 上的安卓应用仍处于早期访问阶段（测试版）。在我的快速测试中，它工作符合预期，但我已经很久没有使用它了。因此，当依靠它进行跨平台会话时，可能会出现预期的小问题。",-1)),s[27]||(s[27]=t("p",null,"在任何情况下，它都适用于每种用例的大量功能。如果你还没有使用过，请试一试。",-1)),s[28]||(s[28]=t("hr",null,null,-1)),t("p",null,[s[7]||(s[7]=o("via: ",-1)),l(n,{href:"https://itsfoss.com/sonobus/"},{default:i(()=>[...s[6]||(s[6]=[o("https://itsfoss.com/sonobus/",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=o("作者：",-1)),l(n,{href:"https://itsfoss.com/author/ankush/"},{default:i(()=>[...s[8]||(s[8]=[o("Ankush Das",-1)])]),_:1}),s[13]||(s[13]=o(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[9]||(s[9]=[o("lujun9972",-1)])]),_:1}),s[14]||(s[14]=o(" 译者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[10]||(s[10]=[o("geekpi",-1)])]),_:1}),s[15]||(s[15]=o(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[o("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=o("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[o("LCTT",-1)])]),_:1}),s[19]||(s[19]=o(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[o("Linux中国",-1)])]),_:1}),s[20]||(s[20]=o(" 荣誉推出",-1))])])}const x=e(d,[["render",m]]);export{C as __pageData,x as default};
